Section WithSegs.
Variable segs : list Segment.

(* [comment removed for export] *)
Fixpoint log_apart (E : env) (log : list sentry) (A n : Z) : Prop :=
  match log with
  | [] => True
  | SE a w _ :: rest => (estart E a + Z.of_nat w <= A \/ A + n <= estart E a) /\ log_apart E rest A n
  end.

Fixpoint log_inside (E : env) (log : list sentry) (W : list ivl) : Prop :=
  match log with
  | [] => True
  | SE a w _ :: rest => inside W (estart E a) (Z.of_nat w) /\ log_inside E rest W
  end.

(* [comment removed for export] *)
Fixpoint log_wr (m : word -> option byte) (E : env) (log : list sentry) : Prop :=
  match log with
  | [] => True
  | SE a w _ :: rest => (forall j, 0 <= j < Z.of_nat w -> wview segs m (wa (estart E a + j)) <> None) /\ log_wr m E rest
  end.

