(* [comment removed for export] *)
Fixpoint replay1 (A : Z) (bs : list byte) (a : Z) (ws : list byte) : list byte :=
  match ws with
  | [] => bs
  | b :: ws' =>
      let bs' := if (Z.leb A a && Z.ltb a (A + Z.of_nat (length bs)))%bool then upd_bytes bs (Z.to_nat (a - A)) [b] else bs in
      replay1 A bs' (a + 1) ws'
  end.

Fixpoint replay (E : env) (log : list sentry) (A : Z) (bs : list byte) : list byte :=
  match log with
  | [] => bs
  | SE a w v :: rest => replay1 A (replay E rest A bs) (estart E a) (word_to_le_bytes w (edenot E v))
  end.

